/*
 * LOKMANGAL — site settings. The one file to edit when the site moves to another server.
 *
 * On AWS Amplify you do NOT edit this file: the addresses come from the Amplify environment variables (see amplify.yml and DEPLOY.md),
 * which write js/env-config.js during every build:
 *     LOKMANGAL_API_BASE   https://api.lokmangal.in               the Python backend (EC2)
 *     LOKMANGAL_PDF_BASE   https://media.lokmangal.in/pdf/        where the weekly PDFs are (S3 behind CloudFront)
 *
 * API_BASE = where the Python backend (backend/app.py) lives:
 *   ""                         same address as this website (the backend also serves the site: SERVE_FRONTEND=true)
 *   "https://api.example.com"  the backend runs on its own server (website hosted on Amplify, Netlify ...)
 *
 * It is chosen for you:
 *   on this PC / your Wi-Fi (localhost, 192.168.x.x ...)  - always the backend running here, never the production one,
 *                                                           so testing can not touch the real data:
 *       page opened from the backend itself (http://localhost:5000)         -> ""
 *       page opened from another local server (Live Server :5500, ...)      -> http://<same host>:5000
 *   on the internet (Amplify, your own domain ...)        -> API_BASE_PRODUCTION below (or LOKMANGAL_API_BASE)
 *       (leave it "" when the site has no backend: it then runs from its built-in data)
 */
(function () {
  var env = window.LOKMANGAL_ENV || {};            // written by the Amplify build (js/env-config.js); {} on a PC

  var API_BASE_PRODUCTION = env.API_BASE || "";   // e.g. "https://api.lokmangal.in"
  var DEV_API_PORT = "5000";      // PORT in backend/.env

  // Where the weekly PDFs are read from. "" = this website's own assets/pdf/ folder (a PC, or while the 68 PDFs are still in the repo).
  // On the live site: the CloudFront address of the bucket's pdf/ folder - the backend stores new PDFs there.
  var PDF_BASE = env.PDF_BASE || "";

  // Weekly PDFs on the website.
  //   true  = "PDF online वाचा / download" for every issue whose file is in assets/pdf/ (lokmangal-weekly-<no>.pdf)
  //   false = NO PDF anywhere: no buttons, tags, banner or wording (the weekly issues themselves stay)
  var WEEKLY_PDF = true;

  // Reader comments under a news item. They are kept in the reader's own browser only (nobody else sees them), so they are
  // switched off. Turn on only after the site has a real comments database.
  var COMMENTS = false;

  var cfg = (window.LOKMANGAL_CONFIG = window.LOKMANGAL_CONFIG || {});
  if (typeof cfg.WEEKLY_PDF !== "boolean") cfg.WEEKLY_PDF = WEEKLY_PDF;
  if (typeof cfg.COMMENTS !== "boolean") cfg.COMMENTS = COMMENTS;
  if (typeof cfg.PDF_BASE !== "string") cfg.PDF_BASE = PDF_BASE;
  if (typeof cfg.API_BASE !== "string") {
    var host = location.hostname;
    var local = host === "localhost" || host === "127.0.0.1" || host === "[::1]" ||
      /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host);
    var base = API_BASE_PRODUCTION;
    if (local) {
      base = location.port && location.port !== DEV_API_PORT
        ? location.protocol + "//" + host + ":" + DEV_API_PORT
        : "";
    }
    cfg.API_BASE = base;
  }
  cfg.API_BASE = cfg.API_BASE.replace(/\/+$/, "");
})();
